document.addEventListener("DOMContentLoaded",()=>{if("undefined"!=typeof AOS&&AOS.init({duration:800,easing:"ease-in-out-cubic",once:!0,offset:50,delay:100,disable:window.matchMedia("(prefers-reduced-motion: reduce)").matches}),"undefined"!=typeof VanillaTilt&&!window.matchMedia("(pointer: coarse)").matches&&window.innerWidth>768){const e=document.querySelectorAll(".experience-card, .project-card, .achievement-card, .blog-card");VanillaTilt.init(e,{max:5,speed:400,glare:!0,"max-glare":.2,scale:1.02})}});